enum class Policy { KEEP, REPLACE, APPEND }

val queue = mutableMapOf<String, MutableList<String>>()

fun enqueueUnique(name: String, policy: Policy, work: String) {
    val existing = queue[name]
    when {
        existing == null -> queue[name] = mutableListOf(work)
        policy == Policy.KEEP -> {}
        policy == Policy.REPLACE -> queue[name] = mutableListOf(work)
        policy == Policy.APPEND -> existing += work
    }
}

fun main() {
    listOf(Policy.KEEP to "a", Policy.KEEP to "b", Policy.APPEND to "c",
        Policy.REPLACE to "d", Policy.APPEND to "e")
        .forEach { (p, w) -> enqueueUnique("sync", p, w) }
    println(queue)
}

